  maxBombs: DEFAULT_PLANNER_OPTIONS.maxBombs,
  fuseTicks: DEFAULT_PLANNER_OPTIONS.fuseTicks,
  flameTicks: DEFAULT_PLANNER_OPTIONS.flameTicks,
